-- claim_level_bonus_v4: validates recency from ad_events.created_at against ad_ttl_seconds
CREATE OR REPLACE FUNCTION claim_level_bonus_v4(
  p_user_id uuid,
  p_level int,
  p_bonus_multiplier numeric,
  p_idempotency_key uuid,
