cation":"none","active":true},{"task_id":"d77d227c-f88e-4f9f-9b09-d7f4fd0998f2","unlock_level":14,"kind":"in_app","reward_payload":{"coin_multiplier":2.19,"tickets":12},"verification":"none","active":true},{"task_id":"587b3029-1f15-4e8e-ba38-e7763238834c","unlock_level":15,"kind":"in_app","reward_payload":{"coin_multiplier":2.29,"tickets":12},"verification":"none","active":true}]}'::jsonb;
